window.__BUNDLE__={"generatedAt":"2026-11-02T19:47:54.508852+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-10-26","archiveCutoff":"2021-11-03","addedToday":20,"addedThisRun":20,"fetchStats":{"hf":307,"arxiv":1388,"total":1695},"freshness":{"latestPaperDate":"2026-11-02","latestPublishedDate":"2026-11-02","latestBatchCount":244,"newInLast24h":285,"newInLast48h":285},"historyTotal":29171,"topicCounts":{"Multi-Agent":3115,"Evaluation":16002,"Planning":2129,"Memory":562,"Code Agent":1167,"Interpretability":981,"Agentic RAG":1553,"Agentic Search":2077,"RL for LLM":1555,"Reasoning":7824,"Hallucination":1280,"Post-Training":3242,"Alignment":3790,"World Model":584,"Tool Use":1456,"Agent Safety":2731,"Computer Use":391,"Reflection":1043,"VLM Training":2282,"LLM Training":3762,"Fine-tuning":4526,"Multimodal Agent":169,"Agent Framework":955,"Error Attribution":187,"Data Engine":578},"count":36,"recentTotal":2087,"archiveCount":0,"archiveTotal":27084,"sources":{"hf":57,"arxiv":2030,"semanticScholar":0},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"url":"https://arxiv.org/abs/2610.40738","source":"hf","date":"2026-11-02","authors":["Aman Tiwari","Akshay Kalkunte","Akintunde Oladipo","Jash Shah","Tara Bogavelli","Hoang Nguyen","Nishanth Madhusudhan","Vishal Juneja","Sridhar Nemala","Srinivas Sunkara","Sathwik Tejaswi Madhusudhan","Shruthan Radhakrishna","Masoud Hashemi","Kelechi Ogueji","Khalil Slimi","Saloni Mittal","Pulkit Pattnaik","Shashank Maiya","Dhruv Jhamb","Esakkivel Esakkiraja","Katrina Stankiewicz","Gabrielle Gauthier Melançon","Fanny Riols","Amit Saha","Lakshmi Sirisha Chodisetty","Nitin Aggarwal","Anil Madamala","Sagar Davasam","Segan Subramanian","Vikas Yadav","Sai Rajeswar Mudumba"],"submittedDate":"2026-10-29","hfUrl":"https://huggingface.co/papers/2610.40738","arxiv":"https://arxiv.org/abs/2610.40738","id":"arxiv:2610.40738","topics":["LLM Training","Tool Use","Reasoning","Fine-tuning"],"pdf":"https://arxiv.org/pdf/2610.40738.pdf","title":"Apriel Voice 27B Preview: An Open Model for Speech, Reasoning, and Tool Use","upvotes":32,"tags":["LLM Training","Tool Use","Reasoning","Fine-tuning"],"announceDate":"2026-11-02","abstract":"A capable voice assistant must do more than recognize words; it must understand requests, reason over context, sustain conversations, and act through tools. We present Apriel Voice 27B Preview, an open speech-language model that unifies these capabilities within a shared reasoning backbone while retaining text and image input modalities. Built on the post-trained Gemma 4 26B-A4B checkpoint, Apriel Voice directly processes speech and generates both responses and tool calls without requiring a separate dialogue model. We introduce a two-stage training procedure to adapt the model to speech. The first stage establishes the speech interface, while the second jointly adapts the projector and backbone through supervised fine-tuning, text replay, and source-dependent cross-entropy and forward Kullback--Leibler divergence supervision. Automatically constructed speech-conditioned dialogues provid"},{"url":"https://arxiv.org/abs/2610.40799","source":"hf","date":"2026-11-02","authors":["Yijia Fan","Xilin He","Yilei Jiang","Dongming Wu","Jiaxu Wang","Xiangyu Yue"],"hfUrl":"https://huggingface.co/papers/2610.40799","arxiv":"https://arxiv.org/abs/2610.40799","id":"arxiv:2610.40799","topics":["Post-Training","LLM Training","VLM Training","Tool Use","Fine-tuning","RL for LLM"],"pdf":"https://arxiv.org/pdf/2610.40799.pdf","title":"CaPtain: A Pipeline for Post-Training Code-as-Policy Robot Agents","upvotes":18,"tags":["Post-Training","LLM Training","VLM Training","Tool Use","Fine-tuning"],"abstract":"Across coding, web, and tool-use tasks, language-model agents are now routinely trained with the same recipe: supervised fine-tuning (SFT) to learn the interface, then multi-turn reinforcement learning (RL) to master it. Code-as-policy (CaP) casts robot manipulation in the same form, as the policy writes code against robot APIs and reads back the results, so the same recipe should apply. Yet existing CaP agents sidestep training: they either prompt closed frontier models or delegate manipulation to pre-trained vision-language-action models (VLAs) and high-level skills, while small open vision-language models (VLMs) fail outright. We present CaPtain, an open post-training pipeline that turns a small open VLM into a capable CaP agent, with no VLA, frontier model, or privileged state at test time. CaPtain trains and deploys the policy inside CaPtain-Harness, which exposes low-level percepti"},{"url":"https://arxiv.org/abs/2610.42141","source":"hf","date":"2026-11-02","authors":["Shengguang Wu","Suning Huang","Cherie Ho","Ria Doshi","Hao Zhu","Serena Yeung-Levy"],"submittedDate":"2026-10-30","hfUrl":"https://huggingface.co/papers/2610.42141","arxiv":"https://arxiv.org/abs/2610.42141","id":"arxiv:2610.42141","topics":["LLM Training","Evaluation"],"pdf":"https://arxiv.org/pdf/2610.42141.pdf","title":"RoboArchitect: Automating the Design of Robotic Agents with Persistent Memory","upvotes":5,"tags":["LLM Training","Evaluation"],"announceDate":"2026-11-02","abstract":"Recent work shows that a frozen robot policy performs far better inside an agent harness, where control code decides when to query the policy, consult vision tools, or command the arm directly. Yet today these harnesses are built by hand and redesigned for each new robot or benchmark. We show that harness design can be automated, offering a strong alternative to finetuning on a novel setup. In RoboArchitect, a coding model observes a robot's rollouts, diagnoses failures, and iteratively revises the harness around the frozen policy. The harness evolves on a set of episodes for its optimization and is evaluated on held-out scenes and tasks. Without updating any model weights, RoboArchitect raises average success from 9.7% to 43.3% on unseen scenes (4.5x) and from 12.7% to 40.2% on unseen tasks (3.2x), across multiple benchmarks and policies. The gains are largest where the benchmark is far"},{"url":"https://arxiv.org/abs/2610.41260","source":"hf","date":"2026-11-02","authors":["Yiqi Liang","Xiaodong Cun"],"submittedDate":"2026-10-30","hfUrl":"https://huggingface.co/papers/2610.41260","arxiv":"https://arxiv.org/abs/2610.41260","id":"arxiv:2610.41260","topics":["Reasoning"],"pdf":"https://arxiv.org/pdf/2610.41260.pdf","title":"SketchDirector: Complex Scene Sketching via Agentic Layout Reasoning and Detail Refinement","upvotes":1,"tags":["Reasoning"],"announceDate":"2026-11-02","abstract":"Existing sketch generation methods often rely on image guidance and are largely limited to individual objects or simplified scenes, leaving text-guided complex scene sketching underexplored. We present SketchDirector, an agentic framework that mimics the human sketching workflow for automatic multi-concept scene sketching. Given a scene-level text prompt, SketchDirector first employs a large language model~(LLM) to decompose the scene into multiple draft assets, where each is represented by a set of Bézier curves. Then, an agentic reasoning loop iteratively plans and executes their spatial arrangement, guided by self-evolving memory. Finally, a detail refinement module leverages diffusion priors to enhance sketch quality while preserving geometric structure. To support future research and applications in multi-concept scene sketch generation, we further introduce the \\textit{MCSketch8K} "},{"url":"https://arxiv.org/abs/2610.42053","source":"arxiv","date":"2026-11-02","authors":["Pengfei Zhou","Yixing Ma","Zhengfeiyang Zhang","Haoyuan Chen","Zhenglin Wan","Hexin Wang","Wangbo Zhao","Yang You"],"submittedDate":"2026-10-30","hfUrl":"https://huggingface.co/papers/2610.42053","arxiv":"https://arxiv.org/abs/2610.42053","id":"arxiv:2610.42053","topics":["Reasoning"],"pdf":"https://arxiv.org/pdf/2610.42053.pdf","title":"REA: A Routed Embodied Agent Runtime for Asynchronous Brain-Cerebellum Control","upvotes":43,"tags":["Reasoning"],"announceDate":"2026-11-02","abstract":"Foundation models are becoming remarkably reliable at high-level reasoning, yet they remain too slow and costly to serve as fine-grained controllers. Conversely, fast policies like VLAs and whole-body controllers offer more efficient reflexes, but struggle to generalize. While pairing a deliberative brain (foundation models) with a reactive cerebellum (fast policies) seems natural for embodied systems, two obstacles remain: methods are built and scored on incompatible stacks, and their asynchronous coordination is difficult. For example, an agent that calls the VLA in the agentic loop can stall the fast execution, while a VLA that calls the agent on errors tends to re-trigger fallbacks repeatedly or completely miss silent failures. To address this, we propose REA (Routed Embodied Agent), a unified runtime where a deliberative System 2, an embodied router System 1 and reactive System 0 po"},{"url":"https://arxiv.org/abs/2610.42149","source":"arxiv","date":"2026-11-02","authors":["Byungwoo Jeon","Yoonwoo Jeong","Hyunseok Lee","Minsu Cho","Jinwoo Shin"],"submittedDate":"2026-10-30","hfUrl":"https://huggingface.co/papers/2610.42149","arxiv":"https://arxiv.org/abs/2610.42149","id":"arxiv:2610.42149","topics":["LLM Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"pdf":"https://arxiv.org/pdf/2610.42149.pdf","title":"Latent Reasoning in Continuous Space for Unified Multimodal Models","upvotes":24,"tags":["LLM Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"announceDate":"2026-11-02","abstract":"Unified Multimodal Models (UMMs) achieve remarkable success on diverse multimodal understanding and generation tasks, yet they still struggle to effectively leverage language-based chain-of-thought reasoning for image generation. As a result, existing reasoning-augmented UMMs often fail to inherit the test-time scaling and fine-grained controllability observed in large language models. We attribute this failure to a fundamental modality mismatch: reasoning is performed in a discrete token space, whereas image generation operates in a continuous space. To bridge this gap, we introduce a Latent Reasoning framework in Continuous space (LARC), which alleviates the token-level bottleneck by reasoning over continuous hidden states. Specifically, the training framework consists of two stages: (i) curriculum supervised fine-tuning (SFT), and (ii) information-gain reinforcement learning (RL). Fir"},{"url":"https://arxiv.org/abs/2610.40992","source":"arxiv","date":"2026-11-02","authors":["Junwei Wu","Runze Yan","Yuzhang Xie","Hanqi Luo","Ziwei Dong","Jiaying Lu","Xiao Hu","Carl Yang"],"submittedDate":"2026-10-29","arxiv":"https://arxiv.org/abs/2610.40992","id":"arxiv:2610.40992","topics":["Post-Training","LLM Training","Reasoning","Planning","Evaluation","Fine-tuning"],"pdf":"https://arxiv.org/pdf/2610.40992.pdf","title":"Can Personal Requirements Become Supervision for Planning?","upvotes":0,"tags":["Post-Training","LLM Training","Reasoning","Planning","Evaluation"],"announceDate":"2026-11-02","abstract":"Managing multiple chronic conditions through diet requires satisfying disease- and medication-specific requirements jointly across meals and days while preserving established eating habits. These requirements are public in clinical guidelines and drug labels, yet turning them into a feasible plan for one person remains difficult for language-model agents. In our dietitian-approved weekly planning evaluation built from NHANES, thirteen models, from medically fine-tuned 8B models to GPT-6.1 Sol, pass fewer than 3% of complete plans through direct generation. Explicit rules, higher reasoning effort, or model-directed tools leave GPT-6.1 Sol at no more than 8%. We present Noura, which pairs LLM planning with executable personal specifications instantiated from public clinical guidance and individual health and dietary profiles. During planning, the specification grounds foods, optimizes port"},{"url":"https://arxiv.org/abs/2610.41564","source":"arxiv","date":"2026-11-02","authors":["Mingyang Liu","Qingcan Kang","Shixiong Kai","Tao Zhong","Mingxuan Yuan","Xin Li","Linqi Song"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41564","id":"arxiv:2610.41564","topics":["Error Attribution","Post-Training","Planning","Evaluation","Reflection"],"pdf":"https://arxiv.org/pdf/2610.41564.pdf","title":"Verify--Backtrack Loop: Structured Precondition Recovery for Long-Horizon Language Agents","upvotes":0,"tags":["Error Attribution","Post-Training","Planning","Evaluation","Reflection"],"announceDate":"2026-11-02","abstract":"Language agents increasingly tackle long-horizon tasks in interactive environments, where actions often depend on latent preconditions. The core difficulty is not trajectory length but recovery: when a prerequisite is missing or an earlier decomposition fails, trying another plausible action rarely helps. ReAct and later reflection or adaptive-planning methods support local correction, but express recovery as free-form text, with no explicit control state linking the terminal goal, the active goal, and the failure source. We introduce the Verify--Backtrack Loop (VBL), a training-free extension of ReAct that turns precondition discovery and failure diagnosis into structured planning-state updates. VBL maintains the task decomposition as a bounded goal stack and, on goal activation, execution failure, or material state change, jointly verifies two horizons---whether the active goal contrib"},{"url":"https://arxiv.org/abs/2610.40798","source":"arxiv","date":"2026-11-02","authors":["Zhifei Hu","Alexandra I. Cristea","Adel Bibi","Jialin Yu"],"submittedDate":"2026-10-29","arxiv":"https://arxiv.org/abs/2610.40798","id":"arxiv:2610.40798","topics":["LLM Training","Evaluation","Fine-tuning","World Model"],"pdf":"https://arxiv.org/pdf/2610.40798.pdf","title":"Beyond Plausible Prediction: Safety Sufficiency in Web World Models","upvotes":0,"tags":["LLM Training","Evaluation","Fine-tuning","World Model"],"announceDate":"2026-11-02","abstract":"Web world models increasingly predict the consequences of candidate actions before agents act, yet a plausible predicted future does not necessarily support the correct safety decision. In a matched human evaluation of 3,000 predictions from ten frozen open models, 86.1% are judged semantically plausible. However, several models exhibit highly asymmetric authorisation behaviour, combining low false-safe execution with poor recall of clarifiable ASK cases and a strong preference for BLOCK. This motivates safety sufficiency: whether a predictive interface preserves and exposes the policy-decisive information required to distinguish actions that may be EXECUTED, require clarification through ASK, or should be BLOCKED. We introduce SafeWebWorld, a benchmark for evaluating safety sufficiency across five web-safety domains through action-conditioned futures, policy-decisive evidence, and polic"},{"url":"https://arxiv.org/abs/2610.41754","source":"arxiv","date":"2026-11-02","authors":["Yuquan Li","Xinyang Jiang","Yuhao Xue","Cairong Zhao"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41754","id":"arxiv:2610.41754","topics":["LLM Training","Reasoning","Interpretability","Fine-tuning"],"pdf":"https://arxiv.org/pdf/2610.41754.pdf","title":"Multimodal In-Context Learning with Explicit Rule Induction","upvotes":0,"tags":["LLM Training","Reasoning","Interpretability","Fine-tuning"],"announceDate":"2026-11-02","abstract":"A central challenge in multimodal in-context learning (MICL) arises from tasks that are ill-defined without context and require uncovering the underlying rules from demonstrations. Existing methods predominantly treat MICL as direct input-output mapping, overlooking the importance of explicitly inducing and reasoning over such rules, limiting both performance and interpretability. We propose ERIM, Explicit Rule-Induction for Multimodal In-Context Learning, a unified framework that enhances MICL by explicitly inducing the latent rules governing demonstration samples. Leveraging the reasoning ability of multi-modal large language model (MLLM), ERIM constructs rule-centric MICL datasets, introduces explicit supervision for rule induction, and fine-tunes MLLM to perform explicit rule-induction via a two-stage training strategy that combines mixed cold-start supervised fine-tuning with reinfo"},{"url":"https://arxiv.org/abs/2610.41296","source":"arxiv","date":"2026-11-02","authors":["Minju Gwak","Alan Ritter"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41296","id":"arxiv:2610.41296","topics":["LLM Training","Reasoning","Evaluation","Reflection"],"pdf":"https://arxiv.org/pdf/2610.41296.pdf","title":"Self-Improvement with Auxiliary Rewards: Learning from Verified Traces and Evaluating Transfer","upvotes":0,"tags":["LLM Training","Reasoning","Evaluation","Reflection"],"announceDate":"2026-11-02","abstract":"Answer-level rewards cannot distinguish reasoning traces with equally correct outcomes. We study whether auxiliary trajectory preferences improve small-language-model self-improvement and transfer under limited supervision. We compare confidence-based (SC) and entropy-based metrics (UID-Conj.), which combines global entropy variation and local smoothness, through online reward augmentation and offline training on correct responses. Online experiments adapt Qwen3-1.7B on 30 AIME problems without reference answers; offline experiments use historical AIME problems. UID-Conj. improves the online macro-average across the adaptation benchmark and three transfer benchmarks by 2.08 percentage points over unmodified TTRL. The strongest evidence comes from offline weighted SFT: UID-Conj. exceeds uniform weighting on the same response pool by 1.93 points, with a paired prompt-bootstrap 95\\% CI of ["},{"url":"https://arxiv.org/abs/2610.41629","source":"arxiv","date":"2026-11-02","authors":["Chanseul Cho","Noori Bae","Dongheon Lee","Youngmin Ro"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41629","id":"arxiv:2610.41629","topics":["VLM Training","Reasoning","Evaluation","RL for LLM"],"pdf":"https://arxiv.org/pdf/2610.41629.pdf","title":"GRIT: Gradient Masking for Visually Misgrounded Tokens in Text-Rich Reasoning","upvotes":0,"tags":["VLM Training","Reasoning","Evaluation","RL for LLM"],"announceDate":"2026-11-02","abstract":"Reinforcement learning with verifiable rewards (RLVR) has recently been extended to vision-language models (VLMs), yet its effectiveness remains limited for text-rich reasoning tasks. We highlight a key factor contributing to this limitation: models frequently arrive at correct final answers despite misperceiving visual information during intermediate steps. We define this phenomenon as Correct-but-Visually-Misgrounded Reasoning (CVMR). Because standard RLVR rewards only final-answer correctness, it fails to differentiate between properly grounded and misgrounded reasoning, reinforcing both equally. Through token-level analysis, we reveal that CVMR tokens exhibit distinct attention patterns that differ systematically from well-grounded ones. Based on this observation, we propose GRIT, a training framework that incorporates visual grounding into RLVR to mitigate the impact of CVMR. Furthe"},{"url":"https://arxiv.org/abs/2610.40998","source":"arxiv","date":"2026-11-02","authors":["Tiejin Chen","Maunil Vyas","Huaiyuan Yao","Hua Wei"],"submittedDate":"2026-10-29","arxiv":"https://arxiv.org/abs/2610.40998","id":"arxiv:2610.40998","topics":["Post-Training","LLM Training","Evaluation","RL for LLM"],"pdf":"https://arxiv.org/pdf/2610.40998.pdf","title":"Steering Vectors as a Training Signal in LLM Post-Training","upvotes":0,"tags":["Post-Training","LLM Training","Evaluation","RL for LLM"],"announceDate":"2026-11-02","abstract":"Steering vectors (SVs) are residual-stream directions that shift the behavior of LLMs when added to hidden states at inference time. While prior work has mainly used SVs as post-hoc controls, we ask whether the same directions can also guide parameter updates during post-training. We study this question across supervised learning, including SFT and distillation, and reinforcement learning with verifiable rewards (RLVR). Our framework considers two intervention regimes: a hidden-state hook during teacher-forced supervised training, and an advantage-repair mechanism on wrong rollouts in GRPO. For each regime, we analyze three design axes, which are the steering direction, its placement, and the operation used to combine it with training. In supervised settings, SV injection improves over plain SFT and distillation, with gains scaling with the off-policy gap and reaching up to a $12\\%$ impr"},{"url":"https://arxiv.org/abs/2610.42054","source":"arxiv","date":"2026-11-02","authors":["Xiao Yu","Justin Chih-Yao Chen","Zaid Khan","Hyunji Lee","Mohit Bansal"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.42054","id":"arxiv:2610.42054","topics":["Reasoning","Hallucination","Reflection","RL for LLM"],"pdf":"https://arxiv.org/pdf/2610.42054.pdf","title":"CRoS: Causality Reward on Scrambled CoTs Improves Accuracy and Reasoning Faithfulness","upvotes":0,"tags":["Reasoning","Hallucination","Reflection","RL for LLM"],"announceDate":"2026-11-02","abstract":"Reinforcement learning with verifiable rewards (RLVR) has become the standard method for training language models to reason. However, RLVR typically relies solely on outcome correctness, which does not guarantee that the CoT causally contributes to the final answer. Without this connection, outcome rewards may fail to reinforce high-quality reasoning. Existing causality metrics assess CoT causality by perturbing the CoT, such as deleting reasoning steps or injecting errors, and measuring changes in the final answer. However, these perturbations inevitably alter information in each step. Consequently, high causality scores may reflect sensitivity to information changes introduced by perturbation rather than true causality. Such confounding effects further induce undesirable reasoning behaviors when these metrics are used as training rewards, including generating less informative CoTs and "},{"url":"https://arxiv.org/abs/2610.41998","source":"arxiv","date":"2026-11-02","authors":["Sizhe Chen","Yibo Peng","Jaewon Chang","Chawin Sitawarin","David Wagner"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41998","id":"arxiv:2610.41998","topics":["Agent Safety","Post-Training","LLM Training","Evaluation"],"pdf":"https://arxiv.org/pdf/2610.41998.pdf","title":"SecPO: Principled Adversarial Training for Prompt Injection Security","upvotes":0,"tags":["Agent Safety","Post-Training","LLM Training","Evaluation"],"announceDate":"2026-11-02","abstract":"Recognized as a top threat to AI agents, prompt injection allows instructions from untrusted data (email, documents, websites) to manipulate the agent's operation. The existing best-defended LLM, Meta-SecAlign, is trained with the DPO loss but still suffers from attack success rates (ASRs) approaching 100% under adaptive prompt injections. One reason is that DPO anchors the model around the undefended reference model, which is insecure. We show an idealized reference model---an injection-invariant, utility-preserving oracle---can nevertheless be approximated, as its output distribution in training is interestingly accessible. This new observation motivates a theoretically principled SecPO loss. Another Meta-SecAlign shortcoming is that it trains on weak simulated attacks. We implement an efficient adversarial training (AT) pipeline that synthesizes strong injected inputs (best@240), and "},{"url":"https://arxiv.org/abs/2610.41618","source":"arxiv","date":"2026-11-02","authors":["Chanseul Cho","Jaesung Jun","Dongheon Lee","Youngmin Ro"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41618","id":"arxiv:2610.41618","topics":["VLM Training","Reasoning","Evaluation","Alignment"],"pdf":"https://arxiv.org/pdf/2610.41618.pdf","title":"Attention Maps Know When to Think: Training-Free Difficulty-Aware Chain-of-Thought for Reasoning Segmentation","upvotes":0,"tags":["VLM Training","Reasoning","Evaluation","Alignment"],"announceDate":"2026-11-02","abstract":"Chain-of-Thought (CoT) prompting has become a standard reasoning strategy in Multi-modal Large Language Models (MLLMs), showing strong performance in complex vision-language tasks such as reasoning segmentation. However, our analysis reveals that indiscriminate CoT usage can lead to degraded performance by inducing unnecessary reasoning, a phenomenon we term overthinking. In reasoning segmentation, overthinking often leads to misalignment between the query's intent and visual grounding. To address this, we propose Difficulty-Aware Chain-of-Thought (DA-CoT), a training-free adaptive framework that selectively triggers CoT based on the input's intrinsic difficulty. We find that the entropy of the model's attention maps reliably reflects task difficulty: low entropy indicates confident, localized grounding, while high entropy suggests uncertainty and potential benefit from CoT. DA-CoT uses "},{"url":"https://arxiv.org/abs/2610.40726","source":"arxiv","date":"2026-11-02","authors":["Zichen Bai","Yanli Wang","Yang Liu","Junhao Shi","Xueqin Liu","Jinguo Sun","Muye Li","Shaoqiang Zheng","Xuefei Diao","Zhuwei Zeng","Nan Duan","Peng Cao"],"submittedDate":"2026-10-29","arxiv":"https://arxiv.org/abs/2610.40726","id":"arxiv:2610.40726","topics":["Post-Training","LLM Training","Reasoning","RL for LLM"],"pdf":"https://arxiv.org/pdf/2610.40726.pdf","title":"Li$^{2}$SAO: Lifting Light Singl-Rollout Asynchronous RL Optimization via Group-Relative Actor-Critic Bootstrapping","upvotes":0,"tags":["Post-Training","LLM Training","Reasoning","RL for LLM"],"announceDate":"2026-11-02","abstract":"Asynchronous reinforcement learning (RL) is becoming a mainstream paradigm for post-training large language models (LLMs), as it improves training efficiency by updating the model as rollouts arrive. Recent work argues that group-wise sampling in GRPO does not naturally fit asynchronous RL training because rollout lengths follow a long-tailed distribution, and proposes Single-rollout Asynchronous Optimization (SAO) to improve stability and off-policy behavior, especially on agentic tasks. However, SAO relies on a closed-source value model obtained from scaling value pretraining. In this paper, we analyze GRPO and LiSAO, our lightweight reproduction of SAO without the pretrained value model, on single-turn reasoning and multi-turn agentic tasks. We find that GRPO outperforms LiSAO on reasoning tasks, while the reverse holds on agentic tasks. Since the value model of LiSAO is not yet well "},{"url":"https://arxiv.org/abs/2610.41704","source":"arxiv","date":"2026-11-02","authors":["Minh-Nam Tran","Abulhair Saparov"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41704","id":"arxiv:2610.41704","topics":["Reasoning","Planning","Evaluation","Data Engine"],"pdf":"https://arxiv.org/pdf/2610.41704.pdf","title":"GraphNIAH: A Benchmark for Long-Context Reasoning over Real-World Graphs","upvotes":0,"tags":["Reasoning","Planning","Evaluation","Data Engine"],"announceDate":"2026-11-02","abstract":"The needle-in-a-haystack (NIAH) benchmark was introduced as a test for measuring a model's ability to find small relevant facts within a very large body of input text. However, existing NIAH benchmarks each suffer from one or more of the following limitations: (1) reliance on synthetic data, so their evaluations may not generalize to real-world settings; (2) reuse of previously published datasets, leading to the risk of benchmark contamination; (3) dependence on manual annotation, which requires human effort to create and update data and is prone to future benchmark contamination; and (4) unrealistic simplification of long-context multi-hop reasoning where each next step is trivial given previous steps, while real-world reasoning often requires planning over multiple possible proof paths. To address these limitations, we introduce \\Benchmark, a dynamic benchmark built from real citation "},{"url":"https://arxiv.org/abs/2610.41769","source":"arxiv","date":"2026-11-02","authors":["Dicong Yu","Wenhua Wang","Tian Wang"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41769","id":"arxiv:2610.41769","topics":["LLM Training","Reasoning","Evaluation","Fine-tuning"],"pdf":"https://arxiv.org/pdf/2610.41769.pdf","title":"Stepwise-Querying: Distilling Reasoning without Access to Teacher Chain-of-Thought","upvotes":0,"tags":["LLM Training","Reasoning","Evaluation","Fine-tuning"],"announceDate":"2026-11-02","abstract":"Reasoning distillation is widely used to transfer the reasoning capabilities of large language models to smaller students through teacher-generated supervision. In the black-box setting, however, teachers may expose only final answers and brief solutions, leaving intermediate calculations and validity conditions unavailable and thus limiting the reasoning supervision available for distillation. We propose Stepwise Querying, which elicits step-specific explanations without requiring access to the teacher's internal chain-of-thought (CoT) traces. Independent queries to the same teacher request intermediate derivations, validity checks, and corrections for individual steps, the assembled solutions are then used for standard supervised fine-tuning. Across two teachers, two students, and four mathematics and code benchmarks, our method achieves the highest score in 14 of 16 comparisons with t"},{"url":"https://arxiv.org/abs/2610.40926","source":"arxiv","date":"2026-11-02","authors":["Jialin Song","Xiaodong Liu","Weiwei Yang","Mingqian Feng","Chengquan Guo","Qiyao Ma","Carolyn Buractaon","Anson Ho","Wuyang Chen","Christopher White"],"submittedDate":"2026-10-29","arxiv":"https://arxiv.org/abs/2610.40926","id":"arxiv:2610.40926","topics":["Agent Safety","Post-Training","Evaluation","RL for LLM"],"pdf":"https://arxiv.org/pdf/2610.40926.pdf","title":"CoFiBreak: A Coarse-to-Fine Diversity Reward for Effective Multi-Turn Jailbreak","upvotes":0,"tags":["Agent Safety","Post-Training","Evaluation","RL for LLM"],"announceDate":"2026-11-02","abstract":"Automated red teaming trains an attacker large language model (LLM) to elicit harmful responses from a victim LLM, but reinforcement learning can collapse attackers onto a narrow set of prompts when attack success is the only reward. Such a collapse of attack diversity can bias safety evaluation toward repeatedly testing near-duplicate attack patterns rather than the underlying harmful intents. Existing methods often trade off attack success or inference cost for greater content or strategy diversity. We propose CoFiBreak, a coarse-to-fine diversity reward for Group Relative Policy Optimization (GRPO) that improves attack diversity while preserving strong attack effectiveness and low inference cost. The coarse reward broadens which strategies the attacker uses by encouraging strategies underrepresented within each GRPO group, while the fine reward broadens how those strategies are realiz"},{"url":"https://arxiv.org/abs/2610.41159","source":"arxiv","date":"2026-11-02","authors":["Zhongnan Shi","Keyang Zhou","Siyi Li","Qichao Ying","Xinchen Ma","Shuyi Gong","Wei Tang","Sheng Li","Zhenxing Qian"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41159","id":"arxiv:2610.41159","topics":["Multi-Agent","Evaluation","Alignment","Agent Framework"],"pdf":"https://arxiv.org/pdf/2610.41159.pdf","title":"MATS: A Multi-Agent Framework for Controllable and Reflective Tumor Synthesis","upvotes":0,"tags":["Multi-Agent","Evaluation","Alignment","Agent Framework"],"announceDate":"2026-11-02","abstract":"Synthesizing realistic tumors on medical images helps address data scarcity for clinical AI. Existing diffusion-based methods, however, lack fine-grained attribute-level controllability, closed-loop quality verification, and awareness of which morphological patterns are underrepresented in the target distribution. We present MATS, a multi-agent framework for text-controllable, cross-organ tumor synthesis. Given a target disease, MATS first profiles its morphological distribution over a fine-grained attribute space covering tumor geometry and appearance, and constructs a generation plan that amplifies underrepresented subtypes while keeping common ones dominant. It then localizes the target organ, proposes anatomically valid placement, and executes two-stage diffusion to produce the tumor mask and render texture, each conditioned on the corresponding attributes. A closed-loop reflective m"},{"url":"https://arxiv.org/abs/2610.41389","source":"arxiv","date":"2026-11-02","authors":["Xiwei Liu","Yulong Li","Xinling Zhuang","Xuhui Li","Yichen Li","Haolin Yang","Zhixiang Lu","Yutong Xie"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41389","id":"arxiv:2610.41389","topics":["VLM Training","Reasoning","Evaluation","Reflection"],"pdf":"https://arxiv.org/pdf/2610.41389.pdf","title":"Parse Before You Execute: Efficient Spatial Reasoning with Executable Primitives","upvotes":0,"tags":["VLM Training","Reasoning","Evaluation","Reflection"],"announceDate":"2026-11-02","abstract":"Spatial reasoning in Vision-Language Models (VLMs) has increasingly benefited from tool-integrated pipelines that ground computation in explicit geometry. However, existing systems often compile queries into relatively open-ended artifacts, such as code, task constraints, tool plans, or gathered evidence, leaving what must be resolved before execution under-specified. This can lead to unnecessary tool acquisition and iterative refinement, while still producing plausible reasoning traces from incomplete spatial commitments. We identify this failure mode as under-committed query compilation. To address it, we propose PEPS, a training-free agentic paradigm Parsing Executable Primitives for Spatial reasoning under a typed FESM schema over Frame, Entity, State, and Metric. PEPS follows a parse-before-execute principle: the Parser commits each query to a compact set of executable requirements;"},{"url":"https://arxiv.org/abs/2610.41257","source":"arxiv","date":"2026-11-02","authors":["Zhongyuan Bao","Cunjie He","Lejun Zhang","Zenglin Xu","Yanwei Fu"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41257","id":"arxiv:2610.41257","topics":["LLM Training","Reasoning","Evaluation","Alignment"],"pdf":"https://arxiv.org/pdf/2610.41257.pdf","title":"ReVEAL: Eliciting Role-Aware Latent Visual Evidence from MLLMs for Reasoning Video Object Segmentation","upvotes":0,"tags":["LLM Training","Reasoning","Evaluation","Alignment"],"announceDate":"2026-11-02","abstract":"Reasoning video object segmentation (ReVOS) requires segmenting the target specified by an implicit query throughout a video. Existing MLLM-based methods typically require costly cross-model alignment, tying MLLM training to a downstream segmentation model. We present ReVEAL, a decoupled thinking-with-video framework for ReVOS that elicits role-aware latent visual evidence from MLLM reasoning to directly guide segmentation. ReVEAL introduces Visual Evidence Tokens (VETs) into video reasoning to associate necessary visual regions or entities with target, background, or distractor roles, while a Dynamic Attention Layer Router adaptively aggregates VET-to-video attention across layers into role-specific grounding evidence. We train the MLLM to perform VET-augmented reasoning on our constructed ReVEAL-47K dataset, with a Contrastive Attention Grounding Loss as auxiliary supervision to apply "},{"url":"https://arxiv.org/abs/2610.41254","source":"arxiv","date":"2026-11-02","authors":["Brian Tang","Kang G. Shin"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41254","id":"arxiv:2610.41254","topics":["VLM Training","Evaluation","Alignment","Fine-tuning"],"pdf":"https://arxiv.org/pdf/2610.41254.pdf","title":"Hawkeye: Reading Illegible Text with Vision Language Models","upvotes":0,"tags":["VLM Training","Evaluation","Alignment","Fine-tuning"],"announceDate":"2026-11-02","abstract":"While modern Vision-Language Models (VLMs) have been remarkably successful in general scene text recognition, they consistently struggle with the long-tail distribution of text that is degraded by motion blur or low resolution. These limitations are particularly apparent in egocentric applications like smart glasses, where text is often captured in noisy environments. In this paper, we introduce the \\textbf{BSTRB} (Blurry Scene Text Recognition Benchmark), a novel benchmark of 8,398 noisy image samples with high-fidelity annotations derived from 1,699 real-world video sequences. To support this, we present \\textbf{Hawkeye}, a VLM fine-tuned on BSTRB to read and reason about illegible text by leveraging contextual priors and pixel-level alignment. Our results show that \\name matches much larger VLMs on BSTRB overall and exceeds them on text at or below 20 pixels, in a single pass suited t"},{"url":"https://arxiv.org/abs/2610.41651","source":"arxiv","date":"2026-11-02","authors":["Hao Yin","Tianchen Guo","Heming Du","Yan Ke","Yanbin Liu","Xin Yu"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41651","id":"arxiv:2610.41651","topics":["VLM Training","Reasoning","Evaluation","Reflection"],"pdf":"https://arxiv.org/pdf/2610.41651.pdf","title":"When Depth Lies: Benchmarking Vision-Language Models on Mirror-Induced RGB-D Ambiguity","upvotes":0,"tags":["VLM Training","Reasoning","Evaluation","Reflection"],"announceDate":"2026-11-02","abstract":"Vision-language models (VLMs) have made significant progress in spatial reasoning, particularly by integrating RGB images with depth data, which is often assumed to faithfully reflect physical distances. However, mirrors violate this assumption: they distort depth readings while reproducing object appearances, making reflections difficult to distinguish from real objects. As existing benchmarks rarely consider such reflective scenarios, VLM performance in mirror scenes remains largely unexplored. In this work, we introduce a mirror-centric RGB-D dataset from reflective scenes to evaluate the spatial reasoning capabilities of state-of-the-art VLMs in these scenarios. Specifically, we collect 1,011 RGB-D images from 525 real-world scenes, spanning diverse indoor and outdoor environments, six reflective surface types, and both daytime and nighttime conditions. All images are annotated with "},{"url":"https://arxiv.org/abs/2610.40801","source":"arxiv","date":"2026-11-02","authors":["Jiahe Wu","Bing Cao","Xingyue Guo","Ruipu Zhao","Beiming Yu","Jiekang Feng","Qinghua Hu","Pengfei Zhu"],"submittedDate":"2026-10-29","arxiv":"https://arxiv.org/abs/2610.40801","id":"arxiv:2610.40801","topics":["VLM Training","Reasoning","Evaluation","Fine-tuning"],"pdf":"https://arxiv.org/pdf/2610.40801.pdf","title":"Drone-PUR: From Visual Clue Discovery to Understanding and Reasoning in UAV Scenes","upvotes":0,"tags":["VLM Training","Reasoning","Evaluation","Fine-tuning"],"announceDate":"2026-11-02","abstract":"The reasoning capabilities of vision-language models (VLMs) can be limited by incomplete or inaccurate visual observations in the general domain. In unmanned aerial vehicle (UAV) scenes, small targets, subtle attributes, and changing viewpoints further complicate perception and understanding. Therefore, we introduce Drone-PUR, a dataset and benchmark organized around visual clue discovery, interpretation, and integration, corresponding to the three capability dimensions of perception, understanding, and reasoning. Reasoning samples are designed to require models to combine multiple visual clues to derive visually grounded conclusions. Its 11 tasks provide 175k training and 20k test samples spanning single images, image sequences, cross-modal images, and multiple viewpoints. All test samples undergo human review. Evaluating 22 general-purpose VLMs reveals persistent limitations in spatial"},{"url":"https://arxiv.org/abs/2610.41216","source":"arxiv","date":"2026-11-02","authors":["Kehong Gong","Xiaoxu Zheng","Guanli Hou","Seunghun Lee","Mengqi Guo","Runjia Tan","Zhengyu Wen","Qi Wang","Xiaoyu He","Mingyuan Zhang","Michael Bi Mi"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41216","id":"arxiv:2610.41216","topics":["VLM Training","Reasoning","Evaluation","Reflection"],"pdf":"https://arxiv.org/pdf/2610.41216.pdf","title":"TinyAstral: Transferring Self-Evolving Harnesses to Tiny Generalist Manipulation Agents","upvotes":0,"tags":["VLM Training","Reasoning","Evaluation","Reflection"],"announceDate":"2026-11-02","abstract":"Robot agents built on vision-language models depend on both the planner and its harness: the tools, feedback, memory, and recovery logic around it. Can improvements to a large teacher's harness be carried into a compact agent with lower inference compute cost? We present TinyAstral, a two-stage approach. We first freeze an open-weight teacher and improve its harness through recursive self-improvement (RSI): frontier LLM agents read the teacher's trajectories and propose harness edits, and each edit is accepted only if it passes a paired statistical test. We then freeze the final harness, collect teacher trajectories with reasoning and failure recovery, and distill a small student that replaces the teacher in the same harness. On RoboTwin, harness evolution raises the teacher's success from 33.4% to 63.6%; the final 4B student reaches 62.8%. Across four harness versions, distilled 4B stud"},{"url":"https://arxiv.org/abs/2610.42028","source":"arxiv","date":"2026-11-02","authors":["Yanming Zhang","Eric Papenhausen","Klaus Mueller"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.42028","id":"arxiv:2610.42028","topics":["Reasoning","Evaluation","Interpretability","RL for LLM"],"pdf":"https://arxiv.org/pdf/2610.42028.pdf","title":"CausalXRL: Explainable Reinforcement Learning through Causal Graph Reasoning","upvotes":0,"tags":["Reasoning","Evaluation","Interpretability","RL for LLM"],"announceDate":"2026-11-02","abstract":"Reinforcement learning is a powerful paradigm for training autonomous agents and has achieved impressive performance in complex environments. However, this success often comes at the cost of interpretability, diminishing trust and complicating efforts to debug and improve agent behavior. To address these challenges, we introduce CausalXRL, a novel framework for explainable reinforcement learning (XRL). A key feature of CausalXRL is its use of causal graph reasoning, which provides transparent, structured, multi-level explanations of agent decision-making. We validate CausalXRL through comprehensive case studies and a two-part evaluation: (1) a quantitative analysis of explanation fidelity and causal-structure learning efficiency in benchmark RL environments, and (2) a qualitative expert study assessing explainability in the real-time strategy (RTS) benchmark MicroRTS. The quantitative re"},{"url":"https://arxiv.org/abs/2610.41738","source":"arxiv","date":"2026-11-02","authors":["Minhao Sun","Zhijing Wu","Xian-Ling Mao"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41738","id":"arxiv:2610.41738","topics":["Agentic Search","Post-Training","Reasoning","Evaluation"],"pdf":"https://arxiv.org/pdf/2610.41738.pdf","title":"Search When Needed, Proceed When Reliable: Metacognitive Reliability Supervision for Efficient Agentic Search","upvotes":0,"tags":["Agentic Search","Post-Training","Reasoning","Evaluation"],"announceDate":"2026-11-02","abstract":"Efficient agentic search requires large language models (LLMs) to determine whether they can reliably proceed with their current knowledge or need additional external evidence. Supervision based on final-answer correctness or trajectory-level feedback evaluates realized trajectory performance. However, observed trajectory performance is jointly shaped by stochastic generation, retrieval quality, and downstream reasoning. Such signals therefore provide only indirect evidence of how reliable the current decision state was and how retrieved evidence changed its reliability. An effective reward should encourage search when external information is needed and favor searches that contribute to the answer. To this end, we propose a metacognitive framework for training LLMs to make search decisions based on the reliability of their intermediate reasoning states. Our framework estimates the reliab"},{"url":"https://arxiv.org/abs/2610.41143","source":"arxiv","date":"2026-11-02","authors":["Huancheng Chen","Xiaodi Sun","Zhaoqiong Huang","Michelle Chang","Jingwen Lu"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41143","id":"arxiv:2610.41143","topics":["LLM Training","Evaluation","Fine-tuning","RL for LLM"],"pdf":"https://arxiv.org/pdf/2610.41143.pdf","title":"TalentRL: Strategy-Guided Reinforcement Learning for Hierarchical Skill Routing","upvotes":0,"tags":["LLM Training","Evaluation","Fine-tuning","RL for LLM"],"announceDate":"2026-11-02","abstract":"Natural-language skills enable large language model (LLM) agents to reuse procedures across tasks, yet most systems retrieve individual skills from a flat SkillBank without explicitly modeling the high-level strategy that governs their selection and use. We introduce TalentRL, a strategy-guided reinforcement learning framework for hierarchical routing over procedural memory. Coarse-grained talents represent recurring strategies for skill use, while fine-grained skills provide executable procedures. For each task, the policy model selects a talent that guides execution and softly prioritizes its associated skills during similarity-based retrieval. However, since task outcomes depend jointly on talent selection, retrieved skill context, and downstream execution, terminal rewards alone cannot isolate the contribution of the routing decision. TalentRL therefore trains talent routing with rew"},{"url":"https://arxiv.org/abs/2610.41335","source":"arxiv","date":"2026-11-02","authors":["Ziniu Liu","Xiaoyang Chen","Dezhi Ye","Jie Liu","Jin Ma","Hao Deng"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41335","id":"arxiv:2610.41335","topics":["Agentic RAG","Agentic Search","VLM Training","Evaluation"],"pdf":"https://arxiv.org/pdf/2610.41335.pdf","title":"Pix2Evidence: A Multimodal RAG System for Text and Visual Evidence","upvotes":0,"tags":["Agentic RAG","Agentic Search","VLM Training","Evaluation"],"announceDate":"2026-11-02","abstract":"Retrieval-augmented generation (RAG) over visually rich documents must find both relevant content and the evidence that supports an answer. Screenshot retrieval preserves images and page structure, but written facts within screenshots also need to be searchable. Moreover, topical relevance alone does not identify which retrieved tile contains evidence for the answer. We introduce Pix2Evidence, a multimodal RAG system that encodes each screenshot tile together with its available transcription into a single fused image--text representation, so that layout and readable text are considered jointly during retrieval. To guide evidence selection, a vision-language teacher describes the visible content that supports each training question. We use these descriptions to adapt the retriever, then rerank the retrieved candidates before answer generation. Extensive experiments demonstrate that Pix2Ev"},{"url":"https://arxiv.org/abs/2610.41319","source":"arxiv","date":"2026-11-02","authors":["Yi Zou","Wei Luo","Xuewen Zhang","Zhuang Yan","Pengjie Wang"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41319","id":"arxiv:2610.41319","topics":["Post-Training","Reasoning","Evaluation","Alignment"],"pdf":"https://arxiv.org/pdf/2610.41319.pdf","title":"MILES-Rec: Uncovering Implicit Intents from Mobility Behaviors for Cross-Domain POI Recommendation","upvotes":0,"tags":["Post-Training","Reasoning","Evaluation","Alignment"],"announceDate":"2026-11-02","abstract":"Map applications bridge everyday mobility with local services, creating opportunities to recommend places by uncovering users' implicit intents. However, utility-driven map interactions provide only indirect and incomplete evidence of consumption demands, making it challenging to infer personalized service needs from observed behaviors. We propose MILES-Rec, a cross-domain POI recommendation framework that infers latent service intents from heterogeneous map behaviors and expresses them as prioritized natural language queries. It first learns from progressive reasoning demonstrations that synthesize user profiles and map histories for situation understanding, intent expansion, and query prioritization. We then introduce intent-aligned group relative policy optimization, using subsequent user interactions to reward query relevance and ranked service coverage while penalizing redundancy an"},{"url":"https://arxiv.org/abs/2610.41616","source":"arxiv","date":"2026-11-02","authors":["Wutong Xu","Yun Qu","Haiyan Feng","Qi Wang","Xiangyang Ji"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41616","id":"arxiv:2610.41616","topics":["LLM Training","Evaluation","RL for LLM"],"pdf":"https://arxiv.org/pdf/2610.41616.pdf","title":"What Should LLMs Forget: Reinforcement Unlearning of Knowledge Associations","upvotes":0,"tags":["LLM Training","Evaluation","RL for LLM"],"announceDate":"2026-11-02","abstract":"Large language models (LLMs) acquire extensive factual knowledge during pre-training, which may include sensitive, private, or copyrighted information, motivating the development of unlearning methods that selectively remove specific knowledge while preserving general capabilities. However, existing approaches typically optimize entire responses without explicitly identifying the knowledge to be forgotten, resulting in coarse and uncontrolled forgetting. To address this, we revisit the forgetting target of LLM unlearning and introduce Knowledge Association (KA), which characterizes the association between a query context and its target knowledge and is instantiated by the corresponding conditional predictive distribution, as the fundamental target of forgetting. Based on KA, we propose Knowledge Association Reinforcement Unlearning (KARU), a unified reinforcement learning framework that "},{"url":"https://arxiv.org/abs/2610.41169","source":"arxiv","date":"2026-11-02","authors":["Alexander Detkov","Dashiel Karish","Matthew Oleynikov","Matt Thomson"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41169","id":"arxiv:2610.41169","topics":["LLM Training","Reasoning","Evaluation"],"pdf":"https://arxiv.org/pdf/2610.41169.pdf","title":"ImplicitHop: Evaluating knowledge integration across context and memory","upvotes":0,"tags":["LLM Training","Reasoning","Evaluation"],"announceDate":"2026-11-02","abstract":"The ability to integrate new information and deduce its consequences is central to learning, understanding, and reasoning in large language models (LLMs). Whether information arrives during training or in-context, models must not only store local facts, but propagate their long-range implications globally. To explore information integration in LLMs, we introduce two complementary natural language benchmarks for large-scale evaluation of deductive reasoning as a function of inference depth. The first is a formal graph benchmark enabling controlled evaluation over a wide range of graph topologies and integration tasks; the second is a knowledge composition benchmark grounded in real-world knowledge graphs. We use these benchmarks to compare knowledge integration from information encoded in context versus information encoded in model weights during pretraining, evaluating a set of open mode"},{"url":"https://arxiv.org/abs/2610.41162","source":"arxiv","date":"2026-11-02","authors":["Feng Chen","Jianguo Huang","Yushan Xiao","Yue Li","Bijun Tang","Xuyu Dong","Xingguo Wang","Feiyang Xie","Jianhui Gu","Dongfeng Cao","Hongda Chen","Yongji Gong","Ruiqi Li","Shuxin Li","Xingji Li","Ruitao Lv","Li Song","Lei Wang","Ye Zhang","Xiaoxu Zhao","Xitao Zheng","Bo An","Zheng Liu"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41162","id":"arxiv:2610.41162","topics":["LLM Training","Reasoning","Evaluation"],"pdf":"https://arxiv.org/pdf/2610.41162.pdf","title":"FrontierMat: Benchmarking Language Models at the Frontier of Materials R&D","upvotes":0,"tags":["LLM Training","Reasoning","Evaluation"],"announceDate":"2026-11-02","abstract":"To accelerate materials discovery, language models must be able to address problems at the research frontier. Yet textbook- and examination-derived benchmarks primarily assess established knowledge, leaving performance on frontier research problems largely untested. We introduce FrontierMat, a benchmark of 330 problems drawn from frontier academic and industrial research in fields including aerospace, semiconductors, embodied intelligence and nuclear fusion. Every problem is validated by leading experimentalists and industry experts in its field. Each problem presents a real study and asks the model to infer a withheld outcome or draw a conclusion from selected experimental evidence. Problems are annotated by functional domain, material system and the scale of the governing mechanism; 130 require cross-scale reasoning. The strongest general-purpose model scores only 53.7%, and on matched"},{"url":"https://arxiv.org/abs/2610.41114","source":"arxiv","date":"2026-11-02","authors":["Moonwon Choi","Kisung Nam","Seunggeun Lee"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41114","id":"arxiv:2610.41114","topics":["Post-Training","Alignment","Fine-tuning"],"pdf":"https://arxiv.org/pdf/2610.41114.pdf","title":"Predicting Human-Gain Curves under Local Proxy Optimization from Repeated Ratings","upvotes":0,"tags":["Post-Training","Alignment","Fine-tuning"],"announceDate":"2026-11-02","abstract":"Optimizing a proxy objective can improve human-perceived quality, but the resulting gain can vary with optimization strength. Average proxy-human correlation alone does not reveal how human-perceived quality changes as optimization strength increases. We propose PACE (Proxy Alignment and Curvature Expansion), a pre-optimization diagnostic that uses repeated human ratings to predict the human-gain curve induced by a fixed proxy. The method models proxy optimization as a KL-regularized exponential tilt. At KL radius $d$, the local gain is approximated by $A\\sqrt{d}+Bd$, where $A$ measures first-order proxy-human alignment and $B$ captures the leading second-order correction along the proxy-optimization path. We estimate $A$ and $B$ from repeated human ratings on calibration items and test the resulting gain-curve prediction on held-out evaluation items. Across SummEval, analysis-eligible W"}],"archive":[],"latestPath":"data/latest.json"};
